public class S14 {
    static class Wallet implements Serializable {
        private int coins;
        Wallet(int c) { coins = c; }
        @Serial
        private void writeObject(ObjectOutputStream out) throws IOException {
            out.writeInt(coins * 2);
        }
        @Serial
        private void readObject(ObjectInputStream in) throws IOException {
            coins = in.readInt() + 1;
        }
    }
    public static void main(String[] args) throws Exception {
        ByteArrayOutputStream bout = new ByteArrayOutputStream();
        try (var out = new ObjectOutputStream(bout)) { out.writeObject(new Wallet(5)); }
        try (var in = new ObjectInputStream(new ByteArrayInputStream(bout.toByteArray()))) {
            System.out.println(((Wallet) in.readObject()).coins);
        }
    }
}

